// Generic useReducer syntax
import { useReducer } from 'react'

// Later you'll call it like this:
const [state, dispatch] = useReducer(reducerFunction, initialState)

// Generic reducer example
function myReducer(state, action) {
  // Check what type of action occurred
  if (action.type === 'ACTION_ONE') {
    // Return new state
    return state + 1
  } else if (action.type === 'ACTION_TWO') {
    return state - 1
  }
  // Default: return current state if we don't recognize the action
  return state
}

// Generic useReducer call
function MyComponent() {
  const [myState, dispatch] = useReducer(myReducer, 0)
  // myState holds the current value
  // dispatch is a function we'll use to trigger updates

  return <div>{myState}</div>
}

// Displaying state in JSX
function MyComponent() {
  const [count, dispatch] = useReducer(myReducer, 0)

  return (
    <div>
      <p>Current value: {count}</p>
    </div>
  )
}

// Using dispatch with buttons
function MyComponent() {
  const [count, dispatch] = useReducer(myReducer, 0)

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => dispatch({ type: 'increment' })}>+</button>
      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
    </div>
  )
}

// Adding a new action is just two steps:

// 1. Add case to reducer:
function myReducer(state, action) {
  if (action.type === 'reset') {
    return 0  // Reset to initial value
  }
  // ...other cases
}

// 2. Add UI to dispatch it:
<button onClick={() => dispatch({ type: 'reset' })}>Reset</button>
